# COUNTS MUST match the literal asserted by data/figures/s7-q048/generate.py.
# Retrieval rebuilt offline: each candidate circuit is run with the SAME transpile
# and simulator seeds as the figure's job.
import numpy as np
from qiskit import QuantumCircuit
from qiskit.transpiler.preset_passmanagers import generate_preset_pass_manager
from qiskit_ibm_runtime import SamplerV2
from qiskit_ibm_runtime.fake_provider import FakeManilaV2

COUNTS = {"100": 443, "101": 429, "001": 58, "000": 62, "111": 2, "011": 1, "110": 5}
backend = FakeManilaV2()
pm = generate_preset_pass_manager(optimization_level=1, backend=backend, seed_transpiler=42)


def body(key):
    qc = QuantumCircuit(3)
    if key == "A":
        qc.x(0); qc.h(2)
    elif key == "B":
        qc.x(2); qc.h(0)
    elif key == "C":
        qc.h(0); qc.cx(0, 2)
    elif key == "D":
        qc.x(2); qc.ry(np.pi / 3, 0)
    elif key == "E":
        qc.x(2); qc.h(1)
    qc.measure_all()
    return qc


def run(qc):
    sampler = SamplerV2(mode=backend)
    sampler.options.simulator.seed_simulator = 17
    return sampler.run([pm.run(qc)], shots=1000).result()[0].data.meas.get_counts()


def tvd(a, b):
    keys = set(a) | set(b)
    return 0.5 * sum(abs(a.get(k, 0) - b.get(k, 0)) for k in keys) / 1000


proven, evidence, observed = [], {}, {"figure": COUNTS}
for key in "ABCDE":
    c = run(body(key))
    top2 = sorted(sorted(c, key=c.get, reverse=True)[:2])
    d = tvd(c, COUNTS)
    m = c == COUNTS
    observed[key] = {"counts": c, "tvd_vs_figure": round(d, 3)}
    evidence[key] = (f"same seeds give {c} (two largest bars {top2}); total-variation distance from the "
                     f"figure's counts = {d:.3f}; identical to the figure: {m}")
    if m:
        proven.append(key)
    else:
        assert d > 0.15, (key, d)
emit_verdict({"answer": proven, "evidence": evidence, "observed": observed})
